gcbT(){return"\u06a9\u0644\u06cc\u06a9 \u0645\u0639\u0645\u0648\u0644\u06cc \u0641\u0642\u0637 \u0645\u062d\u062a\u0648\u0627\u06cc \u062a\u0628 \u0641\u0639\u0644\u06cc \u0631\u0627 \u0639\u0648\u0636 \u0645\u06cc\u200c\u06a9\u0646\u062f. \u0644\u0627\u0646\u06af\u200c\u067e\u0631\u0633 \u0631\u0648\u06cc \u0622\u06cc\u062a\u0645 \u0645\u0646\u0648 \u0647\u0645\u0627\u0646 \u0631\u0641\u062a\u0627\u0631 \u06af\u0632\u06cc\u0646\u0647\u0654 \u0628\u0627\u0644\u0627 \u0631\u0627 \u062f\u0627\u0631\u062f (\u062a\u0628 \u0645\u0648\u062c\u0648\u062f \u06cc\u0627 \u062a\u0628 \u062c\u062f\u06cc\u062f)."},
gcGI(){return"\u0638\u0627\u0647\u0631 \u0644\u0627\u0646\u0686\u0631"},
gcGH(){return"\u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u0638\u0627\u0647\u0631\u06cc \u0644\u0627\u0646\u0686\u0631"},
gcGJ(){return"\u0631\u0646\u06af \u067e\u0633\u200c\u0632\u0645\u06cc\u0646\u0647"},
gcH_(){return"\u0630\u062e\u06cc\u0631\u0647"},
gcGP(){return"\u0630\u062e\u06cc\u0631\u0647 \u0634\u062f"},
gbnV(){return"\u062d\u0633\u0627\u0628 \u06a9\u0627\u0631\u0628\u0631\u06cc"},
gcGY(){return"\u067e\u0646\u0644 \u06a9\u0627\u0645\u0644"},
gbnW(){return"\u0627\u06cc\u0646 \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u0631\u0627 \u0686\u0637\u0648\u0631 \u0628\u0627\u0632 \u06a9\u0646\u06cc\u062f\u061f"},
